const rawUrl = window.location.href;
const normalizedUrl = decodeURIComponent(rawUrl);
const normalizedPrefix = decodeURIComponent('file:///path/to/user/Calibre%20书库');
const contents = document.querySelectorAll('.calibreEbookContent');
const content = contents.length === 1 ? contents[0] : null;
if (!normalizedUrl.startsWith(normalizedPrefix)) throw new Error('Calibre file URL prefix mismatch');
if (!content) throw new Error(`Expected exactly one .calibreEbookContent, found ${contents.length}`);

for (const id of [
  'automa-calibre-reader-style-v3',
  'automa-calibre-reader-style-v4',
  'automa-calibre-reader-content-style-v5',
  'automa-calibre-reader-panel-style-v5',
  'automa-calibre-reader-content-style-v6',
  'automa-calibre-reader-panel-style-v6',
  'automa-calibre-reader-content-style-v7',
  'automa-calibre-reader-panel-style-v7',
  'automa-calibre-reader-panel-v5',
  'automa-calibre-reader-toggle-v5'
]) document.getElementById(id)?.remove();

const contentStyle = document.createElement('style');
contentStyle.id = 'automa-calibre-reader-content-style-v7';
contentStyle.textContent = `
  :root {
    --automa-font-sans: "HarmonyOS Sans SC", "HarmonyOS Sans", system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", "Helvetica Neue", Helvetica, Arial, "PingFang SC", "Hiragino Sans GB", "Microsoft YaHei UI", "Microsoft YaHei", "Source Han Sans SC", "Noto Sans CJK SC", "WenQuanYi Micro Hei", sans-serif, "Apple Color Emoji", "Segoe UI Emoji";
    --automa-font-mono: ui-monospace, SFMono-Regular, "SF Mono", Menlo, Consolas, "Liberation Mono", "Roboto Mono", monospace, "HarmonyOS Sans SC", "PingFang SC", "Microsoft YaHei", sans-serif;
  }
  html, body, .calibreMain, .calibreEbookContent { font-family: var(--automa-font-sans) !important; }
  html { font-size: 16px !important; font-synthesis: none !important; -webkit-text-size-adjust: 100%; }
  body { font-weight: 400 !important; line-height: 1.68 !important; letter-spacing: .01em; -webkit-font-smoothing: antialiased; -moz-osx-font-smoothing: grayscale; }
  code, pre, kbd, samp { font-family: var(--automa-font-mono) !important; }
  .calibreEbookContent h1 { margin: 1.2em 0 .8em !important; text-align: center !important; font-size: clamp(1.75rem, 4vw, 2.4rem) !important; line-height: 1.3 !important; font-weight: 700 !important; }
  .calibreEbookContent h2 { margin: 1.6em 0 .7em !important; font-size: clamp(1.4rem, 3vw, 1.9rem) !important; line-height: 1.35 !important; font-weight: 700 !important; }
  .calibreEbookContent h3 { margin: 1.4em 0 .6em !important; font-size: clamp(1.2rem, 2.5vw, 1.55rem) !important; line-height: 1.4 !important; font-weight: 700 !important; }
  .calibreEbookContent h4, .calibreEbookContent h5, .calibreEbookContent h6 { margin: 1.2em 0 .5em !important; line-height: 1.45 !important; font-weight: 700 !important; }
  .calibreEbookContent p { margin: 0 0 1em !important; font-size: 1rem !important; line-height: 1.75 !important; overflow-wrap: anywhere !important; }
  .calibreEbookContent a { color: #1d4ed8 !important; text-decoration: underline !important; text-decoration-thickness: .08em; text-underline-offset: .15em; }
  .calibreEbookContent a:hover, .calibreEbookContent a:focus-visible { color: #1e3a8a !important; }
  .calibreEbookContent blockquote { margin: 1.2em 0 !important; padding: .7em 1em !important; border-left: 4px solid #cbd5e1 !important; background: #f8fafc !important; color: #374151 !important; }
  .calibreEbookContent ul, .calibreEbookContent ol { margin: 1em 0 !important; padding-left: 2em !important; line-height: 1.75 !important; }
  .calibreEbookContent li { margin: .35em 0 !important; }
  .calibreEbookContent strong, .calibreEbookContent b { font-weight: 700 !important; }
  .calibreEbookContent em, .calibreEbookContent i { font-style: italic !important; }
  .calibreEbookContent hr { margin: 2em 0 !important; border: 0 !important; border-top: 1px solid #d1d5db !important; }
  .calibreEbookContent sub, .calibreEbookContent sup { font-size: .75em !important; line-height: 0 !important; }
  .calibreEbookContent table { width: 100% !important; max-width: 100% !important; table-layout: auto !important; border-collapse: collapse !important; overflow-wrap: anywhere !important; }
  .calibreEbookContent th, .calibreEbookContent td { padding: .5em .65em !important; border: 1px solid #d1d5db !important; text-align: left !important; vertical-align: top !important; overflow-wrap: anywhere !important; }
  html, body, .calibreMain, .calibreEbookContent { width: 100% !important; max-width: none !important; min-width: 0 !important; margin-left: 0 !important; margin-right: 0 !important; box-sizing: border-box !important; background: #fff !important; }
  html, body { min-height: 100% !important; margin-top: 0 !important; margin-bottom: 0 !important; padding: 0 !important; overflow-x: hidden !important; }
  .calibreMain { margin: 0 !important; padding: 0 !important; }
  .calibreEbookContent { display: block !important; padding: 2rem 3rem !important; overflow-x: hidden !important; overflow-wrap: anywhere !important; }
  parsererror { display: none !important; }
  .calibreEbookContent img, .calibreEbookContent svg, .calibreEbookContent video, .calibreEbookContent canvas { display: block !important; max-width: 100% !important; width: auto !important; height: auto !important; object-fit: contain !important; }
  .calibreMeta, .calibreToc, .calibreEbNav, .calibreEbNavTop { display: none !important; }
  @media (max-width: 720px) { .calibreEbookContent { width: calc(100vw - 24px) !important; max-width: calc(100vw - 24px) !important; padding: 16px !important; } }
`;
document.head.appendChild(contentStyle);

const panelStyle = document.createElement('style');
panelStyle.id = 'automa-calibre-reader-panel-style-v7';
panelStyle.textContent = `
  #automa-calibre-reader-panel-v7 { position: fixed; top: 0; right: 0; width: 300px; height: 100vh; z-index: 2147483000; overflow: auto; box-sizing: border-box; padding: 16px; color: #1f2937; background: rgba(255,255,255,.98); border-left: 1px solid #d1d5db; box-shadow: -4px 0 16px rgba(0,0,0,.12); font: 14px/1.5 system-ui, sans-serif; }
  #automa-calibre-reader-panel-v7[hidden] { display: none !important; }
  #automa-calibre-reader-toggle-v7 { position: fixed; top: 16px; right: 300px; z-index: 2147483001; border: 1px solid #9ca3af; border-radius: 6px; padding: 6px 9px; color: #111827; background: #fff; cursor: pointer; }
  #automa-calibre-reader-panel-v7 h2, #automa-calibre-reader-panel-v7 h3 { margin: 0 0 10px; color: #111827; }
  #automa-calibre-reader-panel-v7 section { margin-bottom: 18px; }
  #automa-calibre-reader-panel-v7 .automa-v5-nav { display: flex; gap: 8px; flex-wrap: wrap; }
  #automa-calibre-reader-panel-v7 button, #automa-calibre-reader-panel-v7 a { color: #1d4ed8; }
  #automa-calibre-reader-panel-v7 button { cursor: pointer; border: 1px solid #cbd5e1; border-radius: 4px; padding: 5px 8px; background: #f8fafc; }
  #automa-calibre-reader-panel-v7 ul { margin: 0; padding-left: 18px; }
  #automa-calibre-reader-panel-v7 li { margin: 5px 0; }
  #automa-calibre-reader-panel-v7 .automa-v5-meta { white-space: pre-wrap; overflow-wrap: anywhere; }
  @media (max-width: 720px) { #automa-calibre-reader-panel-v7 { width: min(86vw, 300px); } #automa-calibre-reader-toggle-v7 { right: min(86vw, 300px); } }
`;
document.head.appendChild(panelStyle);

const panel = document.createElement('aside');
panel.id = 'automa-calibre-reader-panel-v7';
panel.setAttribute('aria-label', 'Calibre 阅读控制面板');
const toggle = document.createElement('button');
toggle.id = 'automa-calibre-reader-toggle-v7';
toggle.type = 'button';
toggle.textContent = '隐藏面板';
toggle.setAttribute('aria-expanded', 'true');
const title = document.querySelector('.calibreMetaTitle')?.textContent.trim() || document.title;
const author = document.querySelector('.calibreMetaAuthor')?.textContent.trim() || '';
const prev = document.querySelector('.calibreEbNavTop a.calibreAPrev');
const next = document.querySelector('.calibreEbNavTop a.calibreANext');
const toc = document.querySelectorAll('.calibreToc a');
const section = (heading, contentNode) => { const s=document.createElement('section'); const h=document.createElement('h3'); h.textContent=heading; s.append(h, contentNode); return s; };
const meta = document.createElement('div'); meta.className='automa-v5-meta'; meta.textContent = [title, author].filter(Boolean).join('\n');
const switchLabel = document.createElement('label'); const switchInput=document.createElement('input'); switchInput.type='checkbox'; switchInput.checked=true; switchLabel.append(switchInput, document.createTextNode(' 风格控制（开启）'));
const panelLabel = document.createElement('label'); const panelInput=document.createElement('input'); panelInput.type='checkbox'; panelInput.checked=true; panelLabel.append(panelInput, document.createTextNode(' 显示面板'));
const nav = document.createElement('div'); nav.className='automa-v5-nav';
for (const link of [prev, next]) if (link) { const button=document.createElement('button'); button.type='button'; button.textContent=link.textContent.trim(); button.addEventListener('click',()=>{ window.location.href=link.href; }); nav.appendChild(button); }
const tocList=document.createElement('ul');
for (const link of toc) { const li=document.createElement('li'); const a=document.createElement('a'); a.href=link.href; a.textContent=link.textContent.trim(); li.appendChild(a); tocList.appendChild(li); }
panel.append(section('风格控制', (() => { const wrap=document.createElement('div'); wrap.append(switchLabel, document.createElement('br'), panelLabel); return wrap; })()), section('书籍信息', meta), section('页面导航', nav), section('目录', tocList));
panel.hidden = false;
document.body.append(panel, toggle);
const styleToggle = (enabled) => { contentStyle.disabled = !enabled; switchLabel.lastChild.textContent = enabled ? ' 风格控制（开启）' : ' 风格控制（关闭）'; };
switchInput.addEventListener('change', () => styleToggle(switchInput.checked));
const setPanelVisible = (visible) => { panel.hidden = !visible; panelInput.checked = visible; toggle.textContent = visible ? '隐藏面板' : '显示面板'; toggle.setAttribute('aria-expanded', String(visible)); };
panelInput.addEventListener('change', () => setPanelVisible(panelInput.checked));
toggle.addEventListener('click', () => setPanelVisible(panel.hidden));
automaNextBlock();
